package br.com.sistemacardapio.catalogo;
import java.math.BigDecimal;import java.time.Instant;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import br.com.sistemacardapio.complemento.*;import br.com.sistemacardapio.empresa.*;import br.com.sistemacardapio.entrega.*;import br.com.sistemacardapio.horario.*;import br.com.sistemacardapio.promocao.*;
@Service public class CardapioPublicoService{private final EmpresaRepository empresas;private final CategoriaRepository categorias;private final ProdutoRepository produtos;private final ProdutoVariacaoRepository variacoes;private final PromocaoRepository promocoes;private final GrupoComplementoRepository grupos;private final ComplementoRepository complementos;private final BairroEntregaRepository bairros;private final HorarioRepository horarios;private final HorarioService horarioService;private final RedeSocialRepository redes;private final JdbcTemplate jdbc;
 public CardapioPublicoService(EmpresaRepository e,CategoriaRepository c,ProdutoRepository p,ProdutoVariacaoRepository v,PromocaoRepository pr,GrupoComplementoRepository g,ComplementoRepository co,BairroEntregaRepository b,HorarioRepository h,HorarioService hs,RedeSocialRepository r,JdbcTemplate j){empresas=e;categorias=c;produtos=p;variacoes=v;promocoes=pr;grupos=g;complementos=co;bairros=b;horarios=h;horarioService=hs;redes=r;jdbc=j;}
 @Transactional(readOnly=true)public CardapioResponse obter(String slug){Empresa e=empresas.findBySlugAndAtivaTrue(slug).orElseThrow(()->new IllegalStateException("Cardápio não encontrado"));UUID id=e.getId();Instant now=Instant.now();List<Produto> ativos=produtos.findAllByEmpresaIdAndAtivoTrueOrderByCategoriaOrdemAscOrdemAscNomeAsc(id);Map<UUID,List<ProdutoResponse>>porCategoria=new LinkedHashMap<>();for(Produto p:ativos){Promocao promo=promocoes.findFirstByProdutoIdAndEmpresaIdAndAtivaTrueAndInicioLessThanEqualAndFimGreaterThanOrderByInicioDesc(p.getId(),id,now,now).orElse(null);List<VariacaoResponse>vs=variacoes.findAllByProdutoIdAndEmpresaIdOrderByOrdemAsc(p.getId(),id).stream().filter(ProdutoVariacao::isAtiva).map(v->new VariacaoResponse(v.getId(),v.getNome(),v.getPreco())).toList();List<GrupoResponse>gs=gruposProduto(p.getId(),id);porCategoria.computeIfAbsent(p.getCategoria().getId(),x->new ArrayList<>()).add(new ProdutoResponse(p.getId(),p.getNome(),p.getDescricao(),p.getPreco(),promo==null?null:promo.getPrecoPromocional(),promo==null?null:promo.getTag(),p.getImagemArquivo()==null?null:p.getImagemArquivo().getId(),p.isDisponivel(),p.getRegraPreco(),vs,gs));}
 List<CategoriaResponse>cs=categorias.findAllByEmpresaIdAndAtivaTrueOrderByOrdemAscNomeAsc(id).stream().map(c->new CategoriaResponse(c.getId(),c.getNome(),c.getDescricao(),porCategoria.getOrDefault(c.getId(),List.of()))).toList();Map<String,String>social=new LinkedHashMap<>();redes.findAllByEmpresaIdAndAtivaTrue(id).forEach(r->social.put(r.getTipo(),r.getUrl()));List<BairroResponse>bs=bairros.findAllByEmpresaIdAndAtivoTrueOrderByOrdemAscNomeAsc(id).stream().map(b->new BairroResponse(b.getId(),b.getNome(),b.getTaxa())).toList();List<HorarioResponse>hs=horarios.findAllByEmpresaIdOrderByDiaSemanaAsc(id).stream().map(h->new HorarioResponse(h.getDiaSemana(),h.isAberto(),h.getHoraInicial()==null?null:h.getHoraInicial().toString(),h.getHoraFinal()==null?null:h.getHoraFinal().toString())).toList();return new CardapioResponse(id,e.getSlug(),e.getNomeFantasia(),e.getDescricao(),e.getWhatsapp(),e.getTelefone(),e.getEndereco(),e.getCorPrimaria(),e.getCorSecundaria(),e.getCorDestaque(),e.getLogoArquivo()==null?null:e.getLogoArquivo().getId(),e.getBannerArquivo()==null?null:e.getBannerArquivo().getId(),horarioService.estaAbertaAgora(id),e.isAceitaEntrega(),e.isAceitaRetirada(),e.getTipoTaxaEntrega(),e.getTaxaEntregaFixa(),e.getPedidoMinimo(),e.getTempoEntregaMin(),e.getTempoEntregaMax(),e.getFreteGratisAcima(),e.getTema(),social,bs,hs,cs);}
 private List<GrupoResponse>gruposProduto(UUID p,UUID e){List<UUID>ids=jdbc.query("select grupo_id from produto_grupo_complemento where empresa_id=? and produto_id=? order by ordem",(rs,n)->rs.getObject(1,UUID.class),e,p);return ids.stream().map(grupos::findById).flatMap(Optional::stream).filter(GrupoComplemento::isAtivo).map(g->new GrupoResponse(g.getId(),g.getNome(),g.isObrigatorio(),g.getMinimo(),g.getMaximo(),complementos.findAllByGrupoIdOrderByOrdemAscNomeAsc(g.getId()).stream().filter(Complemento::isAtivo).map(i->new ComplementoResponse(i.getId(),i.getNome(),i.getPreco())).toList())).toList();}
 public record CardapioResponse(UUID empresaId,String slug,String nome,String descricao,String whatsapp,String telefone,String endereco,String corPrimaria,String corSecundaria,String corDestaque,UUID logoArquivoId,UUID bannerArquivoId,boolean aberta,boolean aceitaEntrega,boolean aceitaRetirada,String tipoTaxaEntrega,BigDecimal taxaEntregaFixa,BigDecimal pedidoMinimo,Integer tempoEntregaMin,Integer tempoEntregaMax,BigDecimal freteGratisAcima,String tema,Map<String,String>redesSociais,List<BairroResponse>bairros,List<HorarioResponse>horarios,List<CategoriaResponse>categorias){}public record CategoriaResponse(UUID id,String nome,String descricao,List<ProdutoResponse>produtos){}public record ProdutoResponse(UUID id,String nome,String descricao,BigDecimal preco,BigDecimal precoPromocional,String tagPromocao,UUID imagemArquivoId,boolean disponivel,String regraPreco,List<VariacaoResponse>variacoes,List<GrupoResponse>grupos){}public record VariacaoResponse(UUID id,String nome,BigDecimal preco){}public record GrupoResponse(UUID id,String nome,boolean obrigatorio,int minimo,int maximo,List<ComplementoResponse>itens){}public record ComplementoResponse(UUID id,String nome,BigDecimal preco){}public record BairroResponse(UUID id,String nome,BigDecimal taxa){}public record HorarioResponse(int diaSemana,boolean aberto,String inicio,String fim){}
}
